def wait_or_give_up(now, deadline, jittered, retry_after):
    delay = jittered if retry_after is None else max(jittered, retry_after)
    if now + delay >= deadline:
        return "give up"
    return round(delay, 2)

print(wait_or_give_up(10.0, 60.0, 0.8, None),
      wait_or_give_up(10.0, 60.0, 0.8, 5.0),
      wait_or_give_up(50.0, 60.0, 1.2, 20.0))

def is_transient(err):
    if isinstance(err, anthropic.APIConnectionError):
        return True
    if isinstance(err, anthropic.APIStatusError):
        return err.status_code == 429 or err.status_code >= 500
    return False

import hashlib

def user_token(email: str) -> str:
    return hashlib.sha256(email.lower().encode()).hexdigest()[:16]
